import { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

function Dashboard() {
  const { user } = useContext(AuthContext);
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const res = await axios.get('http://localhost:5001/api/resume/my', { withCredentials: true });
        setResumes(res.data.data);
      } catch (err) {
        console.error(err);
      }
    }
    if (user) load();
  }, [user]);

  if (!user) return <div style={{ padding: 20 }}>Please login to view your dashboard</div>;

  return (
    <div style={{ padding: 20 }}>
      <h3>{user.name || user.email}'s Dashboard</h3>
      <div>
        {resumes.length === 0 && <p>No resumes uploaded yet.</p>}
        {resumes.map(r => (
          <div key={r._id} style={{ border: '1px solid #ddd', padding: 12, borderRadius: 6, marginBottom: 8 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <div><strong>Score:</strong> {Math.round(r.score || 0)}%</div>
              <div className="muted">{r.createdAt ? new Date(r.createdAt).toLocaleString() : ''}</div>
            </div>
            <div><strong>Matched:</strong> {(r.matchedSkills || r.skills || []).join(', ')}</div>
            <div><strong>Missing:</strong> {(r.missingSkills || []).join(', ') || 'None'}</div>
            <div><strong>Interview Status:</strong> {r.interviewStatus}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Dashboard;
